function fit(){const stage=$('#stage'),box=$('#picture');let row=previewRow(),m=mediaOf(row?.clip)||P.media[0];if(!m)return;const key=[m.id,m.width,m.height,P.aspect].join('|');if(key===fitKey)return;fitKey=key;let ar=P.aspect==='Original'?(m.width||16)/(m.height||9):P.aspect.split(':').map(Number).reduce((a,b)=>a/b);let w=Math.min(stage.clientWidth,stage.clientHeight*ar);box.style.width=w+'px';box.style.height=w/ar+'px';}
