 $('#mediaList').innerHTML=list.map(m=>{const kind=mediaKind(m),thumb=thumbnail(m),uses=usage(P,m.id);return`<div class="asset-card ${m.id===selectedAsset?'active':''}"><button class="media-card" data-media="${esc(m.id)}">${thumb?`<img src="${esc(thumb)}" alt="" loading="lazy">`:`<div class="media-placeholder">${kind==='audio'?'AUDIO':kind==='image'?'STILL':'VIDEO'}</div>`}<span class="media-name">${esc(assetName(m))}</span><small>${kind==='audio'?format(m.duration).slice(3):m.width+' × '+m.height} · ${uses?'使用 '+uses+'箇所':'未使用'}</small>${!linkURL(m)?'<span class="relink">再リンクが必要です</span>':''}</button><div class="asset-actions"><button data-use-asset="${esc(m.id)}">${kind==='audio'?(P.bgm.media===m.id?'BGM使用中':'BGMに使う'):'＋ 配置'}</button><button data-manage-asset="${esc(m.id)}">${kind==='audio'?'試聴・管理':'詳細・管理'}</button></div></div>`}).join('')||'<p class="small-note">該当する素材はありません。</p>';
 $$('[data-media],[data-manage-asset]').forEach(b=>b.onclick=()=>{pause();selectedAsset=b.dataset.media||b.dataset.manageAsset;const row=sequence(P).find(r=>!r.clip.gap&&r.clip.media===selectedAsset);if(row&&b.dataset.media){selected=row.clip.id;activeLayer=row.layer;seek(row.start)}tab='import';render()});
