function assetInspector(m){
 if(!m)return '<div class="control-section"><h2>素材を追加</h2><p>動画・静止画・音声をまとめて選べます。</p><button id="insImport" class="primary wide">＋ 素材を追加</button><button id="setupLink" class="wide">Mac版をダウンロード</button></div>';
 const kind=mediaKind(m),url=linkURL(m),uses=usage(P,m.id);
 return`<div class="control-section"><div class="eyebrow">${kind.toUpperCase()} · ${uses?'IN USE':'UNUSED'}</div>${kind==='image'&&thumbnail(m)?`<img class="asset-detail-image" src="${esc(thumbnail(m))}" alt="${esc(assetName(m))}">`:''}<label for="assetRename">表示名</label><input id="assetRename" value="${esc(assetName(m))}" maxlength="120"><p class="small-note">元ファイル：${esc(m.name)}<br>${(m.size/1e6).toFixed(1)} MB · ${kind==='audio'?format(m.duration):m.width+' × '+m.height}</p>${kind==='audio'&&url?`<audio id="assetAudition" controls preload="metadata" src="${esc(url)}"></audio>`:''}<button id="useSelectedAsset" class="primary wide">${kind==='audio'?'この音声をBGMに使う':'選択レイヤーの末尾へ配置'}</button><button id="removeSelectedAsset" class="wide" ${uses?'disabled':''}>一覧から外す</button><p class="small-note">${uses?'編集中の素材です。一覧から外すには、先にクリップやBGMから外してください。':'未使用。元ファイルを消さず、一覧だけ整理できます。'}</p>${!url?'<p class="info-note">素材を再リンクしてください。同じ元ファイルを追加すると復帰します。</p>':''}</div>
 <div class="control-section"><div class="eyebrow">SOURCE</div><div class="meta-grid">${[['TYPE',kind.toUpperCase()],['CODEC',m.codec||'未検出'],['CONTAINER',m.container||'—'],['FPS',kind==='image'?'—':m.fps||'—'],['TIMING',m.rateMode||'未検出'],['COLOR',m.hdr===true?'HDR':m.hdr===false?'SDR':'未検出'],['AUDIO',m.audio?'あり':'なし']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${kind==='image'?'<p class="small-note">初期表示は5秒。CUTのスライダーや両端ドラッグで延長できます。透明部分は黒背景になります。</p>':''}<button id="insImport" class="wide">＋ 素材を追加</button>${engine&&kind==='video'?'<button id="prepareAgain" class="wide">プロキシを生成 / 再試行</button>':''}<button id="setupLink" class="wide">${engine?'Macエンジンの情報':'Mac版をダウンロード'}</button>${!engine?'<button id="deviceInfo" class="wide">端末版の対応状況</button><button id="lastExport" class="wide">前回のMP4を開く</button>':''}</div>`;
}

function appendMedia(id){if(P.clips.length>=200)return toast('クリップは200個までです。');selectedAsset=id;let m=P.media.find(m=>m.id===id);mutate(()=>{let c=pasteClip(P,clip(m),Math.max(0,...sequence(P).filter(r=>r.layer===activeLayer).map(r=>r.end)),activeLayer);selected=c.id});seek(sequence(P).find(r=>r.clip.id===selected).start)}
