function copySelection(cut=false){const c=current();if(!c)return;clipboard=structuredClone(c);if(cut)remove(false);renderTimeline();toast(cut?'クリップを切り取りました。':'クリップをコピーしました。')}
function pasteSelection(duplicate=false){const source=duplicate?current():clipboard;if(!source)return;if(P.clips.length>=200)return toast('クリップは200個までです。');let at=time;if(duplicate)at=sequence(P).find(r=>r.clip.id===source.id).end;mutate(()=>{selected=pasteClip(P,source,at,duplicate?(source.layer||0):activeLayer).id});seek(at)}

const intentHints={'HIGH FASHION':'静止を長く。動きに強いコントラストを。',RAW:'揺れも、不完全な瞬間も残す。',CINEMATIC:'滑らかな時間と、落ち着いた動き。',CLUB:'動きのピークと、短い間隔を拾う。',DOCUMENTARY:'長い間と自然な流れを尊重する。'};
const colorLabels={exposure:'Exposure',contrast:'Contrast',highlights:'Highlights',shadows:'Shadows',whites:'Whites',blacks:'Blacks',temperature:'Temperature',tint:'Tint',saturation:'Saturation',vibrance:'Vibrance'};
function slider(key,label,value,min,max,step=1,unit=''){return`<div class="control-label"><label for="ctl-${key}">${label}</label><output id="out-${key}">${Number(value).toFixed(step<1?2:0)}${unit}</output></div><input type="range" id="ctl-${key}" data-control="${key}" min="${min}" max="${max}" step="${step}" value="${value}">`}
function option(v,text,sel){return`<option value="${v}" ${sel===v?'selected':''}>${text}</option>`}
function selectControl(key,label,value,options){return`<div class="control-label"><label for="ctl-${key}">${label}</label></div><select id="ctl-${key}" data-control="${key}">${options.map(([v,t])=>option(v,t,value)).join('')}</select>`}
function renderInspector(){let c=current(),m=tab==='import'?(P.media.find(m=>m.id===selectedAsset)||mediaOf(c)||P.media[0]):mediaOf(c),b=$('#inspectorBody');$('#inspectorTitle').textContent=tab.toUpperCase();$('#selectionLabel').textContent=c?(c.gap?'GAP':m?.name||'Missing'): '—';let html='';if(tab==='import'){html=assetInspector(m)}
else if(tab==='cut'){html=canEdit()?`<div class="control-section"><div class="eyebrow">SOURCE RANGE</div><div class="row"><label>IN <input data-number="in" type="number" min="0" max="${c.out}" step=".01" value="${c.in.toFixed(3)}"></label><label>OUT <input data-number="out" type="number" min="${c.in}" max="${sourceLimit(m)}" step=".01" value="${c.out.toFixed(3)}"></label></div><p class="small-note">両端をドラッグして長さを調整。中央は移動。上段V2が優先され、原音も表示中のクリップに切り替わります。</p>${slider('in','開始位置',c.in,0,c.out-.001,.001,' sec')}${slider('out','終了位置',c.out,c.in+.001,m.kind==='image'?Math.max(60,c.out):m.duration,.001,' sec')}<div class="row"><label>配置（秒）<input id="clipStart" type="number" min="0" step=".033333" value="${sequence(P).find(r=>r.clip===c)?.start||0}"></label><label>レイヤー<select id="clipLayer"><option value="0" ${!c.layer?'selected':''}>V1 下段</option><option value="1" ${c.layer===1?'selected':''}>V2 上段</option></select></label></div><div class="row"><button id="moveLeft">← 前へ</button><button id="moveRight">後へ →</button></div></div><div class="control-section"><div class="eyebrow">REFRAME</div>${slider('scale','Scale',c.scale,1,3,.01,'×')}${slider('x','Position X',c.x,0,1,.01)}${slider('y','Position Y',c.y,0,1,.01)}<button id="resetCrop" class="wide">中央に戻す</button></div><div class="control-section"><div class="eyebrow">HOLD LAST FRAME</div>${slider('hold','末尾の静止',c.hold||0,0,5,.1,' sec')}<p class="small-note">最後のフレームを保持します。静止区間の原音は無音です。</p></div>`:blank()}
else if(tab==='motion'){html=canEdit()&&m.kind!=='image'?`<div class="control-section"><div class="eyebrow">TIME SCULPTING</div><div class="speed-hero"><input id="speedNumber" aria-label="速度" type="number" min=".05" max="20" step=".05" value="${c.speed}"><span>×</span></div><div class="preset-grid">${[.05,.1,.25,.5,1,2,4,8,10,20].map(v=>`<button data-speed="${v}" class="${v===c.speed?'selected':''}">${v}×</button>`).join('')}</div><p class="small-note">分割したクリップごとに速度を設定できます。</p>${selectControl('curve','Speed ramp',c.curve,[['constant','Constant'],['linear','Linear'],['ease-in','Ease In'],['ease-out','Ease Out'],['ease-in-out','Ease In / Out']])}${c.curve!=='constant'?slider('endSpeed','End speed',c.endSpeed,.05,20,.05,'×'):''}<canvas id="curveCanvas" class="curve-plot" width="500" height="150" aria-label="速度カーブ"></canvas>${m.fps&&Math.min(c.speed,c.curve==='constant'?c.speed:c.endSpeed)<(+(P.export.fps)||30)/m.fps?`<p class="info-note">${m.fps.toFixed(0)}fps素材では約${((+(P.export.fps)||30)/m.fps).toFixed(2)}×未満でフレームが不足します。</p>`:''}${selectControl('interpolation','Slow motion',c.interpolation,[['duplicate','Frame duplication'],['blend','Frame blending']])}</div><div class="control-section"><div class="eyebrow">STABILIZATION</div>${selectControl('stabilization','補正の強さ',c.stabilization,['OFF','WEAK','MEDIUM','STRONG','HANDHELD','NATURAL','GIMBAL','TRIPOD'].map(v=>[v,v]))}<p class="small-note">強い補正は画角を狭め、端に歪みが出る場合があります。クロップは処理時に自動計算します。事前推定は未対応です。</p><button id="processPreview" class="wide">処理プレビューを生成 ↗</button></div>`:m?.kind==='image'?'<p class="small-note">静止画の表示時間はCUTで調整してください。速度変更・手ぶれ補正は動画用です。</p>':blank()}
else if(tab==='look'){let presets=getPresets();html=canEdit()?`<div class="control-section"><div class="eyebrow">LOOK LIBRARY</div><div class="preset-grid">${Object.keys(presets).map((name,i)=>`<button data-look="${i}">${esc(name)}</button>`).join('')}</div><div class="row"><button id="saveLook">＋ 保存</button><button id="resetLook">リセット</button></div><p class="small-note">GPU試写は近似です。最終色は処理プレビューで確認できます。</p></div><div class="control-section">${Object.entries(colorLabels).map(([k,label])=>slider('color.'+k,label,c.color[k],k==='exposure'?-3:-100,k==='exposure'?3:100,k==='exposure'?.05:1)).join('')}</div><button id="processPreview" class="wide">処理プレビューを生成 ↗</button>`:blank()}
else if(tab==='sound'){html=(canEdit()&&m.kind!=='image'?`<div class="control-section"><div class="eyebrow">ORIGINAL SOUND</div><label><input type="checkbox" id="muteAudio" ${c.audio.mute?'checked':''}> 原音をミュート</label>${slider('audio.volume','Volume',c.audio.volume,0,2,.01)}${slider('audio.fadeIn','Fade in',c.audio.fadeIn,0,Math.min(5,timing(c).duration/2),.1,' sec')}${slider('audio.fadeOut','Fade out',c.audio.fadeOut,0,Math.min(5,timing(c).duration/2),.1,' sec')}<p class="small-note">1.0を超える音量と速度ランプの原音は、処理プレビューで確認してください。</p></div>`:blank())+`<div class="control-section"><div class="eyebrow">BACKGROUND MUSIC</div><label for="chooseBgm">素材一覧から選ぶ</label><select id="chooseBgm"><option value="">BGMなし</option>${P.media.filter(m=>mediaKind(m)==='audio').map(m=>`<option value="${esc(m.id)}" ${P.bgm.media===m.id?'selected':''}>${esc(assetName(m))}</option>`).join('')}</select><p>${esc((P.bgm.media?assetName(P.media.find(m=>m.id===P.bgm.media)):'BGMを追加すると、全体の長さに合わせてループします。'))}</p><button id="addBgm" class="wide">＋ BGMを選択</button>${P.bgm.media?`${slider('bgm.volume','BGM volume',P.bgm.volume,0,2,.01)}${slider('bgm.fadeIn','Fade in',P.bgm.fadeIn||0,0,10,.1,' sec')}${slider('bgm.fadeOut','Fade out',P.bgm.fadeOut||0,0,10,.1,' sec')}<button id="removeBgm" class="wide">BGMを外す</button>`:''}</div>`}
else if(tab==='text'){let t=P.texts[0];html=`<div class="control-section"><div class="eyebrow">TYPOGRAPHY</div><p class="small-note">シーケンス上の秒数で表示区間を指定します。</p>${!t?'<button id="addText" class="wide primary">＋ テキストを追加</button>':`<textarea id="textValue" rows="3" aria-label="表示テキスト">${esc(t.text)}</textarea>${selectControl('text.font','Font',t.font,[['Sans','Sans Serif'],['Serif','Serif'],['Mono','Monospace']])}${selectControl('text.align','Alignment',t.align||'center',[['left','Left'],['center','Center'],['right','Right']])}${slider('text.size','Size',t.size,8,200,1)}${slider('text.x','Position X',t.x,0,1,.01)}${slider('text.y','Position Y',t.y,0,1,.01)}${slider('text.opacity','Opacity',t.opacity,0,1,.01)}${slider('text.fade','Fade',t.fade||0,0,3,.1,' sec')}<div class="row"><label>開始 <input type="number" data-textnum="start" value="${t.start}" min="0" step=".1"></label><label>終了 <input type="number" data-textnum="end" value="${t.end}" min="0" step=".1"></label></div><button id="removeText" class="wide">テキストを削除</button>`}</div>`}
else if(tab==='analyze'){let a=P.analysis.find(a=>a.media===m?.id&&a.intent===P.intent);html=`<div class="control-section"><div class="eyebrow">PHOTOGRAPHER'S EYE</div><h2>強い瞬間を見つける。</h2><p>鮮鋭度、動き、静止、変化の少ない区間を候補として可視化します。</p><button id="scan" class="primary wide" ${!canEdit()||m?.kind==='image'?'disabled':''}>✧ 素材をスキャン</button><p class="small-note">顔・視線・ポーズの意味認識は未実装です。画面全体の特徴量から候補を選びます。素材の自動変更はしません。</p>${a?`<p class="small-note">${esc(a.intent)} · ${a.sampleFps.toFixed(1)} samples/sec · ${a.markers.length}候補</p>`:''}</div><div class="control-section"><div class="eyebrow">EDITORIAL RANDOMIZER</div><button id="randomize" class="wide">別の編集思想を引く ↻</button><div id="randomResult"></div></div>${a?`<div class="control-section"><div class="eyebrow">MOMENTS · SOURCE TIME</div>${a.markers.map((m,i)=>`<button class="marker-card ${m.type}" data-analysis="${i}"><strong>${m.label}</strong><span>${m.time.toFixed(2)}s</span><small>${esc(m.detail)}</small></button>`).join('')}</div>`:''}`}
b.innerHTML=html;bindInspector();if(tab==='motion')drawCurve();}
function getPresets(){let defaults={CLEAN:colors(),HARD:{...colors(),contrast:36,blacks:-18,saturation:-8},COLD:{...colors(),temperature:-22,contrast:12},WARM:{...colors(),temperature:20,highlights:-15},RAW:{...colors(),contrast:-8,saturation:-6},NIGHT:{...colors(),exposure:-.4,temperature:-15,blacks:-20},EDITORIAL:{...colors(),contrast:20,shadows:-10,saturation:-18}};try{return{...defaults,...JSON.parse(localStorage.getItem('pve.looks')||'{}')}}catch{return defaults}}
function setPath(path,value){let c=current();if(c&&['speed','endSpeed','curve'].includes(path))delete c.timingBase;if(path.startsWith('color.'))c.color[path.slice(6)]=value;else if(path.startsWith('audio.'))c.audio[path.slice(6)]=value;else if(path.startsWith('bgm.'))P.bgm[path.slice(4)]=value;else if(path.startsWith('text.'))P.texts[0][path.slice(5)]=value;else c[path]=value}
function bindInspector(){const asset=P.media.find(m=>m.id===selectedAsset)||mediaOf(current())||P.media[0];if($('#assetRename'))$('#assetRename').onchange=e=>{const label=e.target.value.trim();mutate(()=>asset.label=label||asset.name)};if($('#useSelectedAsset'))$('#useSelectedAsset').onclick=()=>mediaKind(asset)==='audio'?useAudio(asset.id):appendMedia(asset.id);if($('#removeSelectedAsset'))$('#removeSelectedAsset').onclick=()=>cleanupAssets([asset.id]);if($('#assetAudition'))$('#assetAudition').onplay=()=>{playing=false;playbackTimeline=null;cancelAnimationFrame(raf);video.pause();bgmAudio.pause();$('#play').textContent='▶';$('#play').ariaLabel='再生'};if($('#clipStart'))$('#clipStart').onchange=e=>{const v=clamp(e.target.value,0,86400);mutate(()=>{anchor(P);current().start=v})};if($('#clipLayer'))$('#clipLayer').onchange=e=>{const v=+e.target.value;mutate(()=>{anchor(P);current().layer=v;activeLayer=v})};const bind=(id,fn)=>{let el=$('#'+id);if(el)el.onclick=fn};bind('insImport',()=>$('#filePicker').click());bind('deviceInfo',showDeviceInfo);bind('lastExport',async()=>{const r=await rememberedExport();if(r)showDeviceResult(r,r.name,{modal,head,esc,status});else toast('保存されたMP4はありません。')});bind('setupLink',showEngine);bind('prepareAgain',()=>prepareMedia(asset.id));bind('moveLeft',()=>move(-1));bind('moveRight',()=>move(1));bind('resetCrop',()=>mutate(()=>Object.assign(current(),{scale:1,x:.5,y:.5})));bind('resetLook',()=>mutate(()=>current().color=colors()));bind('saveLook',()=>{modal(head('ルックを保存')+'<label>プリセット名<input id="lookName" maxlength="30" value="MY LOOK"></label><div class="modal-actions"><button id="confirmLook" class="primary">保存</button></div>');$('#confirmLook').onclick=()=>{let name=$('#lookName').value.trim();if(!name)return;let old=JSON.parse(localStorage.getItem('pve.looks')||'{}');old[name]={...current().color};localStorage.setItem('pve.looks',JSON.stringify(old));$('#modal').close();renderInspector();toast('ルックを保存しました。同じ名前で上書きできます。')}});bind('processPreview',()=>exportProject(true));bind('addBgm',()=>$('#bgmPicker').click());if($('#chooseBgm'))$('#chooseBgm').onchange=e=>e.target.value?useAudio(e.target.value):mutate(()=>{P.bgm.media=null;bgmAudio.pause()});bind('removeBgm',()=>mutate(()=>{P.bgm.media=null;bgmAudio.pause()}));bind('addText',()=>mutate(()=>P.texts.push({id:uid(),text:'UNTITLED',font:'Sans',align:'center',size:48,x:.5,y:.85,opacity:1,fade:.3,start:0,end:Math.max(1,duration())})));bind('removeText',()=>mutate(()=>P.texts=[]));bind('scan',scan);bind('randomize',randomize);if($('#muteAudio'))$('#muteAudio').onchange=e=>mutate(()=>current().audio.mute=e.target.checked);if($('#speedNumber'))$('#speedNumber').onchange=e=>mutate(()=>setPath('speed',clamp(e.target.value,.05,20)));if($('#textValue'))$('#textValue').onchange=e=>mutate(()=>P.texts[0].text=e.target.value);$$('[data-textnum]').forEach(el=>el.onchange=()=>{let n=clamp(el.value,0,Math.max(duration(),1)),t=P.texts[0];if(el.dataset.textnum==='end'&&n<=t.start)return toast('終了は開始より後にしてください。');if(el.dataset.textnum==='start'&&n>=t.end)return toast('開始は終了より前にしてください。');mutate(()=>t[el.dataset.textnum]=n)});$$('[data-number]').forEach(el=>el.onchange=()=>{let c=current(),m=mediaOf(c),value=clamp(el.value,0,sourceLimit(m)),key=el.dataset.number;if(key==='in'&&value>=c.out||key==='out'&&value<=c.in)return toast('INはOUTより前にしてください。');mutate(()=>c[key]=value);seek(sequence(P).find(r=>r.clip.id===c.id).start)});$$('[data-speed]').forEach(el=>el.onclick=()=>mutate(()=>setPath('speed',+el.dataset.speed)));$$('[data-look]').forEach(el=>el.onclick=()=>mutate(()=>current().color={...Object.values(getPresets())[+el.dataset.look]}));$$('[data-control]').forEach(el=>{let recorded=false;el.addEventListener('pointerdown',()=>{pause();checkpoint();recorded=true});el.addEventListener('input',()=>{if(!recorded){pause();checkpoint();recorded=true}let value=el.tagName==='SELECT'?el.value:+el.value;setPath(el.dataset.control,value);renderPreview=null;let o=document.getElementById('out-'+el.dataset.control);if(o)o.textContent=Number(value).toFixed(+el.step<1?2:0);draw();drawCurve();renderTimeline();save()});el.addEventListener('change',()=>{recorded=false;render();syncVideo(true)})});$$('[data-analysis]').forEach(el=>el.onclick=()=>{let c=current(),a=P.analysis.find(a=>a.media===c.media&&a.intent===P.intent),m=a.markers[+el.dataset.analysis],row=sequence(P).find(r=>r.clip.id===c.id);if(m.time<c.in||m.time>=c.out){toast('この候補は選択クリップのIN / OUT外です。元の範囲へ戻すと編集できます。');return}showMarker({...m,source:m.time,time:row.start+outputOffset(m.time-c.in,c),clip:c.id})})}
function drawCurve(){let el=$('#curveCanvas'),c=current();if(!el||!c)return;let ctx=el.getContext('2d');ctx.clearRect(0,0,500,150);ctx.strokeStyle='#273221';ctx.lineWidth=1;for(let y=25;y<150;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(500,y);ctx.stroke()}ctx.strokeStyle='#d4e59b';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=100;i++){let x=15+i*4.7,s=speedAt(i/100,c),y=132-(Math.log(s/.05)/Math.log(400))*114;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.fillStyle='#859775';ctx.font='18px monospace';ctx.fillText('20×',10,22);ctx.fillText('0.05×',10,145)}
function move(delta){const rows=sequence(P).filter(r=>r.layer===(current()?.layer||0)).sort((a,b)=>a.start-b.start),i=rows.findIndex(r=>r.clip.id===selected),other=rows[i+delta];if(!other)return;mutate(()=>{anchor(P);const a=rows[i];a.clip.start=other.start;other.clip.start=a.start});seek(current().start)}

function splitAtSource(c,s){return splitClip(c,s)}
function split(){let row=sequence(P).find(r=>r.clip.id===selected&&time>r.start&&time<r.end)||previewRow();if(!row||row.clip.gap)return;let s=row.clip.in+sourceOffset(time-row.start,row.clip);if(s<=row.clip.in+.001||s>=row.clip.out-.001)return toast('クリップの途中へ再生ヘッドを移動してください。');mutate(()=>{let i=P.clips.indexOf(row.clip),right=splitAtSource(row.clip,s);P.clips.splice(i+1,0,right);selected=right.id});toast('クリップを分割しました。')}
function trimEdge(edge){let c=current(),row=previewRow();if(!c||c.gap||row?.clip.id!==c.id)return toast('選択クリップ内へ再生ヘッドを移動してください。');let t=sourcePosition();if(edge==='in'&&t>=c.out-.001||edge==='out'&&t<=c.in+.001)return;mutate(()=>c[edge]=t);seek(sequence(P).find(r=>r.clip.id===c.id).start)}
function remove(ripple){const c=current();if(!c)return;mutate(()=>{deleteClip(P,c.id,ripple);selected=null});seek(Math.min(time,duration()))}

function undo(redo=false){let from=redo?future:history,to=redo?history:future;if(!from.length)return;pause();to.push(serial());P=sanitize(JSON.parse(from.pop()));selected=P.clips.find(c=>c.id===selected)?.id||P.clips[0]?.id;renderPreview=null;save();render();syncVideo(true)}
function showMarker(m){selected=m.clip;seek(m.time);render();let suggestions=P.intent==='RAW'||P.intent==='DOCUMENTARY'?[1,.7,1]:P.intent==='CLUB'?[2,.3,4]:[1,.2,3];modal(head(m.label)+`<p>${esc(m.detail)}</p><p class="mono">SOURCE ${format(m.source)} · ${esc(P.intent)}</p><div class="modal-actions"><button id="markerCut">ここで分割</button>${m.type==='still'?'<button id="markerHold">静止を0.8秒保持</button>':''}${m.type==='motion'||m.type==='best'?`<button id="markerRamp" class="primary">${suggestions.join(' → ')}×</button>`:''}</div><p class="small-note">適用ボタンを押したときだけ編集します。⌘Zで元に戻せます。</p>`);$('#markerCut').onclick=()=>{$('#modal').close();split()};if($('#markerHold'))$('#markerHold').onclick=()=>{mutate(()=>{let c=current(),s=clamp(m.source,c.in+.002,c.out-.002),i=P.clips.indexOf(c),r=splitAtSource(c,s);if(r){c.hold=.8;if(Number.isFinite(r.start))r.start+=.8;P.clips.splice(i+1,0,r)}});$('#modal').close()};if($('#markerRamp'))$('#markerRamp').onclick=()=>{mutate(()=>{let c=current(),start=Math.max(c.in,m.source-.6),end=Math.min(c.out,m.source+.6),parts=[],orig=structuredClone(c);if(start>c.in+.001)parts.push({...structuredClone(orig),id:uid(),out:start,hold:0});let mid=clamp(m.source,start+.001,end-.001);parts.push({...structuredClone(orig),id:uid(),in:start,out:mid,speed:suggestions[0],endSpeed:suggestions[1],curve:'ease-out',hold:0});parts.push({...structuredClone(orig),id:uid(),in:mid,out:end,speed:suggestions[1],endSpeed:suggestions[2],curve:'ease-in',hold:0});if(end<c.out-.001)parts.push({...structuredClone(orig),id:uid(),in:end});let at=sequence(P).find(r=>r.clip===c).start;for(const part of parts){delete part.timingBase;part.start=at;part.layer=c.layer||0;at+=timing(part).duration}P.clips.splice(P.clips.indexOf(c),1,...parts);selected=parts.find(c=>c.in===start)?.id});$('#modal').close();toast('速度アクセントを適用しました。')};}
const rules=[['SLOW TENSION','動き出す直前を長く。静止から0.1×へ。'],['HARD CUT','動きの途中で切る。次の画へ余韻を渡す。'],['OFF-BEAT CUT','予想した切り替えから、数フレーム遅らせる。'],['MICRO ZOOM','動かない画へ、小さなクロップの変化を。'],['FREEZE','ポーズが決まる一瞬を、0.8秒だけ留める。'],['LONG SILENCE','音を引いて、服と視線の動きに集中する。'],['ABRUPT SPEED','静けさの直後に8×。速度の段差を残す。'],['REVERSE MOMENT','逆再生に似合う動きを探す。V1は提案のみ。'],['EXTREME CROP','顔から離れ、手・布・影のひとつを選ぶ。'],['ASYMMETRIC RHYTHM','長・短・短・長。均等な尺から外れる。']];let lastRule=-1;
function randomize(){let n;do{n=Math.floor(Math.random()*rules.length)}while(n===lastRule);lastRule=n;let[t,d]=rules[n];$('#randomResult').innerHTML=`<div class="random-card"><strong>${t}</strong><p>${d}</p></div><p class="small-note">提案のみ。素材には適用していません。</p>`}
async function metadata(file,url){
 if(globalThis.VideoDecoder){try{const info=await probeFile(file,{thumbnail:true,signal:operationAbort?.signal});if(info.width&&info.duration){const id=uid();if(info.thumbnail)thumbs.set(id,info.thumbnail);delete info.thumbnail;return{id,name:file.name,size:file.size,container:file.name.split('.').at(-1).toUpperCase(),...info}}}catch(e){if(operationAbort?.signal.aborted)throw e}}
 let v=document.createElement('video');v.preload='auto';v.playsInline=true;v.muted=true;
 try{
  const pending=waitForMedia(v,'loadeddata',{signal:operationAbort?.signal});v.src=url;v.load();await pending;
  let m={id:uid(),name:file.name,duration:v.duration,width:v.videoWidth,height:v.videoHeight,size:file.size,fps:null,rateMode:'未検出',codec:null,container:file.name.split('.').at(-1).toUpperCase(),hdr:null,audio:null};
  try{Object.assign(m,await probeFile(file))}catch{}
  if(!Number.isFinite(m.duration)||m.duration<=0)throw Error('動画の長さを取得できません。Mac版で読み込んでください。');
  await seekMedia(v,Math.min(.1,m.duration/2),{signal:operationAbort?.signal});
  let cv=document.createElement('canvas');cv.width=160;cv.height=90;cv.getContext('2d').drawImage(v,0,0,160,90);thumbs.set(m.id,cv.toDataURL('image/jpeg',.7));return m;
 }finally{v.removeAttribute('src');v.load()}
}
function xhrUpload(file){return new Promise((resolve,reject)=>{
 const x=new XMLHttpRequest();uploadRequest=x;x.open('POST','/api/upload');x.setRequestHeader('X-Filename',encodeURIComponent(file.name));
 x.upload.onprogress=e=>{if(e.lengthComputable)progress('Mac内に素材を読み込み中',e.loaded/e.total)};
 x.onload=()=>{uploadRequest=null;try{let d=JSON.parse(x.responseText);x.status===200?resolve(d):reject(Error(d.error))}catch{reject(Error('読み込みに失敗しました。'))}};
 x.onerror=()=>{uploadRequest=null;reject(Error('Macエンジンへの接続が切れました。'))};
 x.onabort=()=>{uploadRequest=null;reject(new DOMException('読み込みをキャンセルしました。','AbortError'))};x.send(file);
})}
async function importFiles(files,isBgm=false){
 if(busy)return toast('現在の処理が終わるまでお待ちください。');pause();busy=true;cancelled=false;progressModal('素材を読み込み中');
 let added=0,errors=[];
 try{
 for(const file of files){
  const already=P.media.find(m=>m.name===file.name&&m.size===file.size&&linkURL(m));if(already){selectedAsset=already.id;continue}
  if(cancelled)break;if(P.media.length>=200){errors.push('素材は200件までです。');break}
  let m,url,retained=false;
  try{
   const kind=fileKind(file);
   if(engine)m=await xhrUpload(file);
   else{
    url=URL.createObjectURL(file);
    if(kind==='image'){
     const info=await probeImage(file,url);m={id:uid(),name:file.name,size:file.size,container:file.name.split('.').at(-1).toUpperCase(),...info};
     thumbs.set(m.id,info.thumbnail);delete m.thumbnail;
    }else if(kind==='audio'){
     const a=new Audio();try{const pending=waitForMedia(a,'loadedmetadata',{signal:operationAbort?.signal});a.src=url;a.load();await pending;
      if(!Number.isFinite(a.duration)||a.duration<=0)throw Error('音声の長さを取得できません。');
      m={id:uid(),name:file.name,kind:'audio',duration:a.duration,width:0,height:0,audio:true,size:file.size,container:file.name.split('.').at(-1).toUpperCase()};
     }finally{a.removeAttribute('src');a.load()}
    }else{m=await metadata(file,url);m.kind='video'}
   }
   if(cancelled)throw new DOMException('中止しました','AbortError');
   const missing=P.media.find(old=>old.name===m.name&&old.size===m.size&&!linkURL(old));
   const duplicate=P.media.find(old=>old.name===m.name&&old.size===m.size&&linkURL(old));
   if(duplicate){selectedAsset=duplicate.id;if(url)URL.revokeObjectURL(url);continue}
   checkpoint();
   if(missing){
    const oldId=missing.id,label=missing.label;
    if(engine){for(const c of P.clips)if(c.media===oldId)c.media=m.id;if(P.bgm.media===oldId)P.bgm.media=m.id;P.analysis=P.analysis.filter(a=>a.media!==oldId);P.media.splice(P.media.indexOf(missing),1,m)}
    else{if(thumbs.has(m.id)){thumbs.set(oldId,thumbs.get(m.id));thumbs.delete(m.id)}m.id=oldId;Object.assign(missing,m);urls.set(m.id,url)}
    if(label){m.label=label;if(!engine)missing.label=label}
   }else{
    P.media.push(m);if(url)urls.set(m.id,url);
    if(mediaKind(m)!=='audio'&&P.clips.length<200){const c=pasteClip(P,clip(m),Math.max(0,...sequence(P).filter(r=>r.layer===activeLayer).map(r=>r.end)),activeLayer);selected=c.id}
   }
   retained=true;selectedAsset=m.id;added++;
   if(!engine&&url){
    localFiles.set(m.id,file);try{progress('再開用に素材を端末へ保存中',.85);await retainFile(m.id,file,operationAbort?.signal);m.retained=true}catch(e){m.retained=false;errors.push(file.name+'：再開用の保存に失敗。次回は再リンクしてください。')}
   }
   if(engine){capsMedia.add(m.id);if(mediaKind(m)==='video'){try{const r=await api('/api/prepare',{media:m.id});Object.assign(m,await watchJob(r.job))}catch(e){errors.push(file.name+'：プロキシ生成 '+e.message)}}}
   save();render();
  }catch(e){if(url&&!retained)URL.revokeObjectURL(url);if(e.name==='AbortError'||cancelled)break;errors.push(file.name+'：'+e.message)}
 }
 $('#modal').close();tab='import';render();if(P.clips.length)await seek(sequence(P).find(r=>r.clip.id===selected)?.start||0);
 if(errors.length)modal(head('読み込み結果')+`<p>${added}件を追加しました。読み込み済みの素材は保持しています。</p><p class="small-note">${errors.map(esc).join('<br>')}</p><div class="modal-actions"><button data-close>閉じる</button></div>`);
 else toast(cancelled?'処理を中止しました。読み込み済みの素材は保持しています。':added+'件の素材を追加しました。音声は「BGMに使う」で適用できます。');
 }finally{busy=false;jobID=null;$('#filePicker').value='';$('#bgmPicker').value=''}
}

function progressModal(title){operationAbort?.abort();operationAbort=new AbortController();lastJobID=null;modal(`<div class="modal-top"><h2>${esc(title)}</h2></div>`+'<div class="progress-track"><div id="progressBar"></div></div><div id="progressLabel" class="progress-caption">準備中…</div><div class="modal-actions"><button id="cancelJob">キャンセル</button></div>');$('#cancelJob').onclick=()=>{cancelled=true;operationAbort?.abort();uploadRequest?.abort();if(jobID)api('/api/cancel',{job:jobID}).catch(()=>{});};}
function progress(operation,value){if($('#progressBar'))$('#progressBar').style.width=clamp(value*100,0,100)+'%';if($('#progressLabel'))$('#progressLabel').textContent=operation+' · '+Math.round(value*100)+'%';status(operation)}
async function watchJob(id){jobID=id;lastJobID=id;while(true){if(cancelled)await api('/api/cancel',{job:id}).catch(()=>{});let j=await api('/api/job/'+id);progress(j.operation,j.progress);if(j.status==='done'){jobID=null;return j.result}if(j.status==='error'||j.status==='cancelled'){jobID=null;throw Error(j.error||'処理を中止しました。')}await new Promise(r=>setTimeout(r,500))}}
async function prepareMedia(id){if(busy)return;busy=true;cancelled=false;progressModal('プロキシを生成');try{let r=await api('/api/prepare',{media:id}),m=await watchJob(r.job);Object.assign(P.media.find(m=>m.id===id),m);save();render();await syncVideo(true);$('#modal').close()}catch(e){errorModal(e,()=>prepareMedia(id))}finally{busy=false;jobID=null}}
function errorModal(e,retry=null){
 const stopped=cancelled||e.name==='AbortError';
 modal(head(stopped?'処理を中止しました':'処理を完了できませんでした')+'<p>編集内容は保持されています。</p>'+(!stopped?'<pre class="code-box">'+esc(e.message)+'</pre>':'')+'<div class="modal-actions">'+(engine&&lastJobID?`<a class="quiet" href="/api/diagnostic/${encodeURIComponent(lastJobID)}" download="video-diagnostic.json">診断記録を保存</a>`:'')+'<button data-close>閉じる</button>'+(retry?'<button id="retryOperation" class="primary">もう一度処理する</button>':'')+'</div>');
 if(retry)$('#retryOperation').onclick=()=>{$('#modal').close();retry()};status(stopped?'処理を中止しました。編集は保持しています。':'処理に失敗しました。編集は保持しています。');
}
async function scan(){if(mediaKind(mediaOf(current()))==='image')return toast('動きの解析は動画素材を選んでください。');if(busy||!canEdit())return;pause();busy=true;cancelled=false;let c=current(),m=mediaOf(c);progressModal('素材を解析');try{let result;if(engine){let r=await api('/api/analyze',{media:m.id,intent:P.intent});result=await watchJob(r.job)}else{let url=linkURL(m);if(!url)throw Error('元動画を再リンクしてください。');const v=document.createElement('video');v.preload='auto';v.playsInline=true;v.muted=true;const cv=document.createElement('canvas');cv.width=cv.height=64;const ctx=cv.getContext('2d',{willReadFrequently:true});scanWorker=new Worker('analysis-worker.js');const ask=(d,transfer=[])=>new Promise((r,j)=>{scanWorker.onmessage=e=>r(e.data);scanWorker.onerror=e=>j(Error(e.message));scanWorker.postMessage(d,transfer)});try{const ready=waitForMedia(v,'loadeddata',{signal:operationAbort?.signal});v.src=url;v.load();await ready;await ask({type:'reset'});let sampleFps=Math.min(4,1800/m.duration),n=Math.max(1,Math.ceil(m.duration*sampleFps));for(let i=0;i<n;i++){if(cancelled)throw Error('解析をキャンセルしました。');let t=Math.min(m.duration-.001,(i+.1)/sampleFps);if(Math.abs(v.currentTime-t)>.0001){await seekMedia(v,t,{signal:operationAbort?.signal})}ctx.drawImage(v,0,0,64,64);let image=ctx.getImageData(0,0,64,64);await ask({type:'frame',time:t,buffer:image.data.buffer},[image.data.buffer]);progress('動き・静止・鮮鋭度を解析中',i/n)}result=await ask({type:'finish',media:m.id,intent:P.intent,duration:m.duration,sampleFps})}finally{scanWorker?.terminate();scanWorker=null;v.removeAttribute('src');v.load()}}delete result.samples;mutate(()=>{P.analysis=P.analysis.filter(a=>a.media!==m.id||a.intent!==P.intent);P.analysis.push(result)});$('#modal').close();status('解析が完了しました。');toast(result.markers.length+'個の候補を表示しました。素材は変更していません。')}catch(e){errorModal(e)}finally{busy=false;jobID=null}}
function showEngine(){if(engine){modal(head('Macエンジン')+`<p>動画はMacの中だけで処理されます。</p><div class="meta-grid">${[['ENGINE',caps.engine],['H.264',caps.ready?'利用可能':'未対応'],['STABILIZER',caps.stabilization?'vidstab':'未導入'],['HDR → SDR',caps.hdr?'利用可能':'未対応']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="small-note">BUILD ${esc(caps.build||'1.0.0')}<br>${esc(caps.version)}</p><p>終了は起動したターミナルで Control+C。元素材のコピー・プロキシ・書き出しはMac内に保存されます。保存先と削除手順はREADMEに記載しています。</p>`);return}modal(head('Macで、フル機能を使う')+`<p>同じ編集画面をMac上で起動します。動画はMacから外へ送信されません。</p><ol><li><p>Mac版をダウンロードし、ZIPを展開します。</p></li><li><p>初回のみ Python 3 と FFmpeg が必要です。Homebrew導入済みの場合：</p><pre class="code-box">brew install python ffmpeg-full</pre></li><li><p>展開したフォルダの <strong>Launch.command</strong> を開きます。起動できない場合は同梱READMEをご確認ください。</p></li></ol><p class="small-note">手ぶれ補正にはlibvidstab対応のFFmpegが必要です。起動後に対応状況を確認できます。現在の編集は「保存」で.projectへ書き出し、Mac版で開いて同じ動画を再リンクしてください。</p><a class="primary download-link" href="personal-video-editor-mac.zip" download>Mac版をダウンロード ↓</a>`)}
function exportDialog(){if(!P.clips.length)return toast('動画を追加してください。');const ex=P.export;modal(head('EXPORT')+`<p class="mono">${esc(P.name)} · ${format(duration())}</p><div class="modal-fields"><label>Destination<select id="exportPreset">${['INSTAGRAM REELS','INSTAGRAM STORIES','INSTAGRAM FEED','YOUTUBE','CUSTOM'].map(v=>option(v,v,ex.preset)).join('')}</select></label><label>Resolution<select id="exportResolution">${['1080p','4K','Source'].map(v=>option(v,v,ex.resolution)).join('')}</select></label><label>Frame rate<select id="exportFps">${['Source','24','30','60'].map(v=>option(v,v,ex.fps)).join('')}</select></label><label>Quality<select id="exportQuality">${['Preview','Standard','High','Maximum'].map(v=>option(v,v,ex.quality)).join('')}</select></label></div><p class="small-note">H.264 / AAC · ${engine?'SDR Rec.709':'SDR'} · MP4<br>Source FPSはSNS互換性を優先し最大60fps。画角プリセットを選ぶとシーケンスの比率も変更します。</p>${!engine?'<p class="info-note">端末版：書き出し中はSafariを開いたままにしてください。速度変更した原音は音程も変化します。手ぶれ補正は平行移動のみ。HDRは正確な変換に未対応のため開始前に停止します。</p>':''}<div class="modal-actions"><button data-close>戻る</button><button id="startExport" class="primary">${engine?'MP4を書き出す':'この端末でMP4を書き出す'} ↗</button></div>`);$('#startExport').onclick=()=>{mutate(()=>{P.export={preset:$('#exportPreset').value,resolution:$('#exportResolution').value,fps:$('#exportFps').value,quality:$('#exportQuality').value};const r={'INSTAGRAM REELS':'9:16','INSTAGRAM STORIES':'9:16','INSTAGRAM FEED':'4:5',YOUTUBE:'16:9'}[P.export.preset];if(r)P.aspect=r});exportProject(false)}}
async function exportProject(preview){if(!engine){await exportDevice(preview);return}if(busy)return toast('現在の処理が終わるまでお待ちください。');if(!P.clips.length)return;busy=true;cancelled=false;pause();progressModal(preview?'処理プレビュー':'MP4書き出し');try{const r=await api('/api/render',{project:P,preview}),result=await watchJob(r.job);modal(head(preview?'処理プレビュー':'書き出し完了')+`<video controls playsinline src="${esc(result.url)}" style="width:100%;max-height:50vh;background:#000"></video><p class="mono">${result.width} × ${result.height} · ${result.fps} FPS · ${format(result.duration)}</p><a class="primary download-link" href="${esc(result.url)}" download="${esc(P.name.replace(/[^\p{L}\p{N} _-]/gu,'_'))}.mp4">MP4を保存 ↓</a><p class="small-note">${result.verified?'全フレーム・音声の検証済み。 ':''}${result.recoveredOutputs?'再生成で復旧しました。 ':''}${preview?'処理プレビューは540pです。カラー・音声・補間・手ぶれ補正を含みます。':'元素材は変更していません。'}</p>`);status(preview?'処理プレビューを生成しました。':'MP4を書き出しました。')}catch(e){errorModal(e,()=>exportProject(preview))}finally{busy=false;jobID=null}}
function saveFile(){P.name=$('#projectName').value.trim()||'Untitled film';save();const file=new File([JSON.stringify(P,null,2)],safeName(P.name,'project'),{type:'application/json'});const url=URL.createObjectURL(file);modal(head('プロジェクトを保存')+`<p>編集内容を保存します。動画本体は含まれません。別の端末へ移す場合は元素材もお持ちください。</p><div class="save-actions"><button id="shareProject" class="primary">共有・ファイルへ保存</button><a href="${url}" class="download-link" download="${esc(file.name)}">.project を保存 ↓</a></div><p id="projectShareStatus" class="small-note"></p>`);const b=$('#shareProject');b.disabled=!canShareFile(file);b.onclick=async()=>{try{await shareFile(file)}catch(e){if(e.name!=='AbortError')$('#projectShareStatus').textContent=e.message}};$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}
async function restoreProjectMedia(){for(const m of P.media){if(localFiles.has(m.id))continue;try{const file=await restoreFile(m.id);if(file){localFiles.set(m.id,file);urls.set(m.id,URL.createObjectURL(file))}}catch{}}}
function showDeviceInfo(){modal(head('端末内で編集する')+`<p>${deviceSupport()?'このブラウザは端末内書き出しの基本APIに対応しています。素材・画角・コーデックは書き出し時に追加確認します。':'端末内書き出しに必要なAPIが不足しています。iPhoneでは最新iOSのSafariでこのページを開いてください。'}</p><button id="deviceCheck" class="primary wide">この端末の書き出しをテスト</button><p>MP4の作成後、「写真・ファイルへ保存」からiOSの共有画面を開きます。「ビデオを保存」または「ファイルに保存」を選んでください。</p><p>再開用の素材はこのブラウザ内に保存します。ブラウザのデータ削除や空き容量不足で失われることがあるため、元素材は残してください。</p><p class="small-note">端末版の手ぶれ補正は平行移動のみ。速度変更した原音は音程も変化します。HDRの正確なSDR変換はMac版で行ってください。iPhone実機での受け入れ検証は未完了です。</p>`);$('#deviceCheck').onclick=deviceCheck}
async function exportDevice(preview){if(busy)return toast('現在の処理が終わるまでお待ちください。');busy=true;cancelled=false;pause();progressModal('端末内でMP4を作成');try{const snapshot=structuredClone(P);const files=[...localFiles].map(([id,file])=>({id,file}));const result=await renderOnDevice(snapshot,files,{preview,signal:operationAbort.signal,onProgress:progress});rememberExport(result,snapshot.name);showDeviceResult(result,snapshot.name,{modal,head,esc,status})}catch(e){errorModal(e,()=>exportDevice(preview))}finally{busy=false;jobID=null}}

function openDialog(){if(engine){api('/api/projects').then(list=>{modal(head('プロジェクトを開く')+`<button id="fromFile" class="wide primary">.project ファイルを開く</button>${list.map((p,i)=>`<button class="project-option" data-project-index="${i}">${esc(p.name)}</button>`).join('')}`);$('#fromFile').onclick=()=>$('#projectPicker').click();$$('[data-project-index]').forEach(b=>b.onclick=async()=>{try{let p=await api('/api/project/'+list[+b.dataset.projectIndex].id);await loadProject(p);$('#modal').close()}catch(e){toast(e.message)}})}).catch(e=>toast(e.message))}else $('#projectPicker').click()}
async function loadProject(p){pause();let next=sanitize(p);checkpoint();P=next;selected=P.clips[0]?.id;time=0;activeMedia=null;if(!engine)await restoreProjectMedia();save();render();syncVideo(true);toast('プロジェクトを開きました。未接続の素材は同じ動画を追加して再リンクできます。')}
const capsMedia=new Set();
async function boot(){if(location.hostname==='127.0.0.1'||location.hostname==='localhost'){try{caps=await api('/api/health');engine=!!caps.ready;let medias=await api('/api/media');for(let m of medias)capsMedia.add(m.id);for(let m of P.media){let actual=medias.find(x=>x.id===m.id);if(actual)Object.assign(m,actual)}if(engine){$('#engineButton').textContent='MAC ENGINE';$('#engineButton').classList.add('connected')}else toast(caps.error||'FFmpegが準備できていません。')}catch(e){toast('Macエンジンに接続できません。Launch.commandから起動してください。')}}if(!engine){$('#engineButton').textContent=deviceSupport()?'DEVICE ENGINE':'BROWSER MODE';await restoreProjectMedia()}render();if(P.clips.length)await syncVideo(true);}
$$('.workflow button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});for(let id of ['addMedia','importSide','importMain'])$('#'+id).onclick=()=>$('#filePicker').click();$('#filePicker').onchange=e=>importFiles([...e.target.files]);$('#bgmPicker').onchange=e=>importFiles([...e.target.files],true);$('#projectPicker').onchange=async e=>{try{await loadProject(JSON.parse(await e.target.files[0].text()));$('#modal').close()}catch(err){toast(err.message)}e.target.value=''};$('#saveProject').onclick=saveFile;$('#openProject').onclick=openDialog;$('#engineButton').onclick=()=>engine?showEngine():showDeviceInfo();$('#exportButton').onclick=exportDialog;$('#projectName').onchange=e=>mutate(()=>P.name=e.target.value.trim()||'Untitled film');$('#intent').onchange=e=>{mutate(()=>P.intent=e.target.value);toast('解析基準を変更しました。再スキャンで新しい候補を表示します。')};$$('[data-aspect]').forEach(b=>b.onclick=()=>mutate(()=>P.aspect=b.dataset.aspect));$('#play').onclick=play;$('#prevFrame').onclick=()=>step(-1);$('#nextFrame').onclick=()=>step(1);$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$('#setIn').onclick=()=>trimEdge('in');$('#setOut').onclick=()=>trimEdge('out');$('#split').onclick=split;$('#deleteClip').onclick=()=>remove(false);$('#ripple').onclick=()=>remove(true);$('#compare').onpointerdown=()=>{compare=true;draw()};document.addEventListener('pointerup',()=>{if(compare){compare=false;draw()}});$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('#stage').requestFullscreen?.()};$('#timelineZoom').oninput=e=>{zoom=+e.target.value;renderTimeline()};$('#zoomIn').onclick=()=>{zoom=clamp(zoom+.5,1,10);$('#timelineZoom').value=zoom;renderTimeline()};$('#zoomOut').onclick=()=>{zoom=clamp(zoom-.5,1,10);$('#timelineZoom').value=zoom;renderTimeline()};$('#ruler').onpointerdown=e=>{const el=$('#ruler');el.setPointerCapture(e.pointerId);const move=ev=>{let rect=el.getBoundingClientRect();seek((ev.clientX-rect.left)/rect.width*duration())};move(e);el.onpointermove=move;el.onpointerup=()=>el.onpointermove=null};
function step(direction){let row=previewRow();if(!row)return;let c=row.clip,m=mediaOf(c);if(c.gap)return seek(time+direction/30);let s=sourceOffset(time-row.start,c)+direction/(m?.fps||30);seek(row.start+outputOffset(clamp(s,0,c.out-c.in),c));status(m?.rateMode==='VFR'?'VFR素材のフレーム送りは平均FPS基準です。':'フレーム送り')}
function shortcuts(){modal(head('キーボードショートカット')+`<div class="keyboard-grid">${[['再生 / 停止','Space'],['後ろへ1秒','J'],['停止','K'],['前へ1秒','L'],['IN / OUT','I / O'],['分割','S'],['コピー / 切り取り','⌘ C / ⌘ X'],['貼り付け / 複製','⌘ V / ⌘ D'],['削除・他のクリップは固定','Delete'],['前詰め削除','Shift Delete'],['フレーム送り','← / →'],['元に戻す','⌘ Z'],['やり直し','⌘ Shift Z'],['プロジェクト保存','⌘ S']].map(([a,b])=>`<span>${a}</span><kbd>${b}</kbd>`).join('')}</div><p class="small-note">速度ランプは32区間の積分で近似します。分割後も元の速度カーブを保持します。</p>`)}$('#shortcuts').onclick=shortcuts;
$('#copyClip').onclick=()=>copySelection();$('#cutClip').onclick=()=>copySelection(true);$('#pasteClip').onclick=()=>pasteSelection();$('#duplicateClip').onclick=()=>pasteSelection(true);$('#snapToggle').onclick=()=>{snapping=!snapping;renderTimeline()};
const keymap={Space:()=>play(),KeyJ:()=>seek(time-1),KeyK:pause,KeyL:()=>seek(time+1),KeyI:()=>trimEdge('in'),KeyO:()=>trimEdge('out'),KeyS:split,ArrowLeft:()=>step(-1),ArrowRight:()=>step(1)};document.addEventListener('keydown',e=>{if($('#modal').open||busy)return;if((e.metaKey||e.ctrlKey)&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){const actions={KeyC:()=>copySelection(),KeyX:()=>copySelection(true),KeyV:()=>pasteSelection(),KeyD:()=>pasteSelection(true),KeyY:()=>undo(true)};if(actions[e.code]){e.preventDefault();actions[e.code]();return}}if(e.metaKey||e.ctrlKey){if(e.code==='KeyS'){e.preventDefault();saveFile();return}if(e.code==='KeyZ'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();undo(e.shiftKey);return}}if($('#modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||busy)return;if(e.key==='?'){shortcuts();return}if(e.code==='Backspace'||e.code==='Delete'){e.preventDefault();remove(e.shiftKey);return}if(keymap[e.code]){e.preventDefault();keymap[e.code]()}});
$('#assetSearch').oninput=e=>{assetQuery=e.target.value;renderMedia()};$('#assetSort').onchange=e=>{assetSort=e.target.value;renderMedia()};$('[data-kind]').forEach(b=>b.onclick=()=>{assetFilter=b.dataset.kind;renderMedia()});$('#removeUnusedAssets').onclick=()=>cleanupAssets(P.media.filter(m=>!usage(P,m.id)).map(m=>m.id));
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dragDepth++;$('#stage').classList.add('dragging')}});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('#stage').classList.remove('dragging')}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();dragDepth=0;$('#stage').classList.remove('dragging');importFiles([...e.dataTransfer.files])}});window.addEventListener('beforeunload',()=>{stillPreview.clear();try{localStorage.setItem('pve.autosave.v1',serial())}catch{}for(let u of urls.values())URL.revokeObjectURL(u);scanWorker?.terminate();painter?.dispose()});$('#modal').addEventListener('cancel',e=>{if(busy){e.preventDefault();toast('処理を止めるには「キャンセル」を押してください。')}});boot();

document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();try{localStorage.setItem('pve.autosave.v1',serial())}catch{}}});
window.addEventListener('pagehide',()=>{try{localStorage.setItem('pve.autosave.v1',serial())}catch{}});

async function deviceCheck(){if(busy)return;busy=true;cancelled=false;pause();progressModal('端末の書き出しテスト');try{const r=await fetch('device-test.mp4');if(!r.ok)throw Error('テスト素材を読み込めません。');const file=new File([await r.blob()],'device-test.mp4',{type:'video/mp4'});const m={id:'device-check',name:file.name,width:160,height:90,duration:1,fps:30,audio:true,hdr:false};const p=project();p.name='Device check';p.media=[m];p.clips=[{...clip(m),speed:.5,endSpeed:2,curve:'ease-in-out'}];p.aspect='9:16';const result=await renderOnDevice(p,[{id:m.id,file}],{preview:true,signal:operationAbort.signal,onProgress:progress});result.test=true;showDeviceResult(result,p.name,{modal,head,esc,status});status('端末テスト成功：映像・音声の生成と全尺検証が完了しました。')}catch(e){errorModal(e,deviceCheck)}finally{busy=false;jobID=null}}
